from pathlib import Path
import json,html
p=Path(__file__).parent
data=json.loads((p/'data-latihan.json').read_text('utf-8'))
e=lambda s:html.escape(str(s))
css='''@page{size:A4;margin:17mm 16mm}*{box-sizing:border-box}body{font:13px/1.56 Arial,sans-serif;color:#183a2c;max-width:1100px;margin:0 auto;padding:25px}h1,h2,h3{line-height:1.27}h1{font-size:30px}h2{font-size:23px;border-bottom:2px solid #d9b45a;padding-bottom:8px;margin:30px 0 20px}h3{font-size:16px;margin:5px 0 9px}.meta{color:#64746c;font-size:12px}.badge{display:inline-block;color:#123f31;background:#e6f3eb;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:bold}.cover{padding:55px 15px;min-height:70vh;border-top:12px solid #103f32;border-bottom:5px solid #d9b45a}.cover p{font-size:17px}.exercise{break-inside:avoid;margin:0 0 19px;border:1px solid #d9e5db;border-radius:10px;padding:14px 16px}.passage{font-size:16px;line-height:1.75;background:#fbfaf5;border-left:4px solid #d9b45a;padding:10px;margin:8px 0}.activities{margin:10px 0 0;padding-left:23px}.activities li{margin:5px 0 9px}.answers{list-style:upper-alpha;padding-left:25px;margin:5px 0}.line{display:block;border-bottom:1px solid #c0cdc2;height:26px}.answerkey{font-size:12px;columns:2;column-gap:20px}.answerkey p{break-inside:avoid;margin:0 0 5px}.chapter{break-before:page}.nav{margin:20px 0}.project{padding:12px;background:#faf5e8;border:1px solid #e9d49b;border-radius:8px;margin:18px 0}.footer{font-size:11px;color:#66776e}button{border:1px solid #a0bdac;background:#eef6f0;padding:9px 14px;border-radius:8px;cursor:pointer}@media print{body{padding:0}.printbutton{display:none}.cover{min-height:200mm}.chapter{page-break-before:always}.exercise{page-break-inside:avoid}}'''
out=['<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Buku Latihan Membaca Lanjutan Kelas II | 144 Sesi</title><style>',css,'</style></head><body>']
out.append('<div class="printbutton"><button onclick="window.print()">Cetak / Simpan melalui fitur cetak browser</button></div>')
out.append('<section class="cover"><div class="badge">PENDAMPING AKADEMIK</div><h1>BUKU LATIHAN MEMBACA LANJUTAN<br>KELAS II SD/MI</h1><p>144 sesi dari 12 bab · Mendengarkan · Membaca · Menulis · Berbicara</p><p>Berbasis pemahaman bacaan, Taksonomi Bloom C1–C6 dan proyek literasi</p><br><p>Nama murid: __________________________________</p><p>Kelas / Sekolah: ______________________________</p><p>Pendamping: __________________________________</p><p class="footer">Materi latihan ini merupakan konten orisinal Pendamping Akademik yang disusun sebagai penguatan literasi kelas II. Bukan salinan buku pemerintah.</p></section>')
out.append('<section><h2>Petunjuk Penggunaan</h2><p>Untuk tiap sesi: (1) pendamping membacakan teks dan anak menjawab; (2) anak membaca nyaring, lalu pendamping mengamati ketepatan dan jeda; (3) anak menulis jawaban singkat; (4) anak menceritakan kembali dengan bahasanya sendiri.</p><p>Gunakan rubrik membaca: 1 = perlu banyak bantuan, 2 = mulai berkembang, 3 = baik dan cukup lancar, 4 = sangat baik dan ekspresif. Jawaban terbuka dapat diterima apabila maknanya sesuai bacaan. Kunci pilihan ganda terdapat di bagian akhir.</p></section>')
for ch in data['bab']:
 n=ch['nomor']; ss=[s for s in data['sesi'] if s['bab']==n]
 out.append(f'<section class="chapter"><h2>Bab {n}. {e(ch["judul"])}</h2><p class="meta">Fokus Bloom {e(ch["bloom"])} · 12 submateri</p>')
 for s in ss:
  opts=s['opsi']
  out.append(f'<article class="exercise"><div class="badge">{e(s["id"])} · {e(s["subbab_title"])} / {e(s["materi_title"])}</div><h3>{e(s["submateri_title"])}</h3><div class="passage">{e(s["bacaan"])}</div><ol class="activities"><li><b>Mendengarkan:</b> dengarkan bacaan dari pendamping. Jawab: <b>{e(s["pertanyaan"])}</b><ol class="answers">'+''.join(f'<li>{e(opt)}</li>' for opt in opts)+'</ol></li><li><b>Membaca:</b> baca nyaring teks di atas. Catatan kelancaran 1 / 2 / 3 / 4 (lingkari).</li><li><b>Menulis:</b> jawab pertanyaan dengan bahasamu sendiri.<span class="line"></span><span class="line"></span></li><li><b>Berbicara:</b> ceritakan kembali isi teks dan jelaskan jawabanmu. <span class="meta">Cek: isi sesuai / alasan sesuai / ucapan jelas.</span></li></ol></article>')
 out.append('<div class="project"><b>Proyek PjBL Bab '+str(n)+':</b> '+e(ch['proyek'])+'<br><br>Catatan hasil: ____________________________________________________________</div></section>')
out.append('<section class="chapter"><h2>Kunci Pilihan Ganda dan Contoh Jawaban</h2><p class="meta">Kunci mendengarkan ditentukan oleh isi teks. Kegiatan menulis dan berbicara dinilai bersama pendamping berdasarkan kesesuaian makna.</p><div class="answerkey">')
for s in data['sesi']:
 letter='ABC'[s['opsi'].index(s['jawaban'])]
 out.append(f'<p><b>{e(s["id"])}.</b> {letter} — {e(s["jawaban"])}</p>')
out.append('</div></section></body></html>')
(p/'latihan-cetak.html').write_text(''.join(out),encoding='utf-8')
print('book length', (p/'latihan-cetak.html').stat().st_size)
